"use client";
import React, { useState, useEffect } from "react";
import { Ruler, ArrowRightLeft, Eye, Shirt, Footprints, Watch, Search } from "lucide-react";
import { sizeData } from "@/data/sizes";

export default function SizeGuidePage() {
  const [activeCat, setActiveCat] = useState<keyof typeof sizeData>("footwear");
  const [gender, setGender] = useState("Men");
  const [baseUnit, setBaseUnit] = useState("");
  const [targetUnit, setTargetUnit] = useState("");
  const [userValue, setUserValue] = useState("");

  useEffect(() => {
    const availableUnits = sizeData[activeCat].units;
    setBaseUnit(availableUnits[0]);
    setTargetUnit(availableUnits[availableUnits.length - 1]);
  }, [activeCat]);

  const categories = [
    { id: "footwear", label: "Footwear", icon: <Footprints size={14} /> },
    { id: "crocs", label: "Crocs", icon: <Footprints size={14} className="text-green-500" /> },
    { id: "apparel", label: "Apparel", icon: <Shirt size={14} /> },
  ];

  return (
    <div className="bg-background text-foreground min-h-screen pb-20">
      <section className="pt-10 pb-12 px-6 text-center">
        <h1 className="text-6xl md:text-[6vw] font-black uppercase italic leading-none mb-8">
          The Fit <span className="opacity-30">Archive.</span>
        </h1>

        <div className="flex justify-center gap-3 mb-10 overflow-x-auto py-2 no-scrollbar">
          {categories.map((cat) => (
            <button
              key={cat.id}
              onClick={() => setActiveCat(cat.id as any)}
              className={`flex items-center gap-3 px-8 py-4 rounded-full text-[10px] font-black uppercase tracking-widest border transition-all ${
                activeCat === cat.id ? "bg-foreground text-background border-foreground shadow-xl" : "border-border opacity-50"
              }`}
            >
              {cat.icon} {cat.label}
            </button>
          ))}
        </div>

        {/* SMART SIZE FINDER */}
        <div className="max-w-xl mx-auto mb-16 bg-background-muted p-2 rounded-full border border-border flex items-center">
          <div className="pl-6 text-brand"><Search size={18} /></div>
          <input 
            type="text" 
            placeholder={`Enter your ${baseUnit}...`}
            className="flex-1 bg-transparent border-none outline-none px-4 text-[12px] font-bold uppercase"
            onChange={(e) => setUserValue(e.target.value)}
          />
          <div className="bg-foreground text-background px-6 py-3 rounded-full text-[10px] font-black uppercase tracking-widest">
            Find My Size
          </div>
        </div>
      </section>

      <section className="max-w-5xl mx-auto px-6">
        <div className="bg-background-muted rounded-[3.5rem] p-6 md:p-10 border border-border">
          <div className="flex flex-col md:flex-row items-center gap-4 mb-10">
            <div className="flex-1 w-full">
               <label className="text-[9px] font-black uppercase opacity-40 ml-4 mb-2 block">I know my size in:</label>
               <select value={baseUnit} onChange={(e) => setBaseUnit(e.target.value)}
                className="w-full bg-background rounded-2xl py-4 px-6 border border-border font-black text-[11px] uppercase tracking-widest">
                {sizeData[activeCat].units.map((u: string) => <option key={u} value={u}>{u}</option>)}
               </select>
            </div>
            <ArrowRightLeft className="mt-6 opacity-20 hidden md:block" />
            <div className="flex-1 w-full">
               <label className="text-[9px] font-black uppercase opacity-40 ml-4 mb-2 block">Show me size in:</label>
               <select value={targetUnit} onChange={(e) => setTargetUnit(e.target.value)}
                className="w-full bg-background rounded-2xl py-4 px-6 border border-border font-black text-[11px] uppercase tracking-widest">
                {sizeData[activeCat].units.map((u: string) => <option key={u} value={u}>{u}</option>)}
               </select>
            </div>
          </div>

          <div className="bg-background rounded-[2rem] border border-border overflow-hidden">
            <table className="w-full">
              <thead>
                <tr className="bg-background-muted/50 border-b border-border">
                  <th className="py-6 px-8 text-left text-[10px] font-black uppercase tracking-widest opacity-40">{baseUnit}</th>
                  <th className="py-6 px-8 text-right text-[10px] font-black uppercase tracking-widest text-brand">Conversion: {targetUnit}</th>
                </tr>
              </thead>
              <tbody>
                {sizeData[activeCat].chart.map((row: any, i: number) => {
                  const isMatch = userValue && row[baseUnit]?.toString().toLowerCase().includes(userValue.toLowerCase());
                  return (
                    <tr key={i} className={`border-b border-border last:border-0 transition-all ${isMatch ? "bg-brand/10 scale-[1.02]" : ""}`}>
                      <td className="py-6 px-8 text-[18px] font-black italic">{row[baseUnit]}</td>
                      <td className="py-6 px-8 text-right text-[18px] font-black italic text-brand-subtle">{row[targetUnit]}</td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        </div>
      </section>

      {/* MEASUREMENT DIAGRAMS */}
      <section className="max-w-5xl mx-auto px-6 mt-16 grid grid-cols-1 md:grid-cols-2 gap-8">
        <div className="space-y-4">
          <h3 className="text-[12px] font-black uppercase tracking-widest">Pro Measurement Guide</h3>
          <p className="text-[11px] opacity-60 leading-relaxed uppercase italic">
            To get the most accurate fit, measure at the end of the day when your feet/body are at their peak volume.
          </p>
          
        </div>
        <div className="bg-brand text-brand-foreground p-10 rounded-[3rem] flex flex-col justify-center">
            <h4 className="text-[10px] font-black uppercase mb-4 tracking-[0.2em]">The Expert Note</h4>
            <p className="text-2xl font-black italic leading-tight">
                "For {activeCat === 'crocs' ? 'Crocs' : activeCat}, if you fall between two size nodes, we always recommend sizing up for maximum comfort."
            </p>
        </div>
      </section>
    </div>
  );
}